    var xPeak = x1 - B / (2 * A);

    // Sanity check: peak should be between x0 and x2
    if (xPeak < x0 || xPeak > x2)
    {
        return { "x" : x1, "y" : y1 };
    }

    var yPeak = y1 + A * (xPeak - x1) * (xPeak - x1) + B * (xPeak - x1);

    return { "x" : xPeak, "y" : yPeak };
}

