    for (var i = 0; i < n; i += 1)
    {
        const e = pointToArcDistance3D(pts[i], circle, theta0, theta1);
        if (e > maxErr)
        {
            maxErr = e;
            maxIdx = i;
        }
    }

    const t = (n > 1) ? (maxIdx / (n - 1)) : 0;
    const uMax = u0 + (u1 - u0) * t;
    return { "maxErr" : maxErr, "uMax" : uMax };
}

/**
