    var maxIdx = 0;
    const n = size(pts);
    for (var i = 0; i < n; i += 1)
    {
        const e1 = pointToArcDistance3D(pts[i], circle1, theta0_a1, theta1_a1);
        const e2 = pointToArcDistance3D(pts[i], circle2, theta0_a2, theta1_a2);
        const e = (e1 < e2) ? e1 : e2;
        if (e > maxErr)
